def matrix_rank_transform(matrix: List[List[int]]) -> List[List[int]]:
    m, n = len(matrix), len(matrix[0])
    by_value = defaultdict(list)
    for i in range(m):
        for j in range(n):
            by_value[matrix[i][j]].append((i, j))
    best = [0] * (m + n)            # best rank so far in row i (i) or column j (m + j)
    answer = [[0] * n for _ in range(m)]
    for value in sorted(by_value):
        cells = by_value[value]
        parent = {}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for i, j in cells:
            parent.setdefault(i, i)
            parent.setdefault(m + j, m + j)
            ri, rj = find(i), find(m + j)
            if ri != rj:
                parent[ri] = rj
        # Rank of each component: one more than its largest row or column rank.
        group_rank = {}
        for node in parent:
            root = find(node)
            group_rank[root] = max(group_rank.get(root, 0), best[node])
        for i, j in cells:
            answer[i][j] = group_rank[find(i)] + 1
        for node in parent:
            best[node] = group_rank[find(node)] + 1
    return answer

