class RLEIterator:
    def __init__(self, encoding: list[int]):
        self.encoding = encoding
        self.i = 0                      # index of the current (count, value) pair

    def next(self, n: int) -> int:
        enc = self.encoding
        # Consume whole pairs that cannot satisfy the remaining request.
        while self.i < len(enc) and enc[self.i] < n:
            n -= enc[self.i]
            self.i += 2
        if self.i >= len(enc):
            return -1                   # ran out of elements
        enc[self.i] -= n                # the current pair has enough copies
