def diameter(root: "Node") -> int:
    if root is None:
        return 0
    order = [root]
    for node in order:              # breadth first order, parents before children
        order.extend(node.children or [])
    height = {}
    best = 0
    for node in reversed(order):    # children are finished before their parent
        top1 = top2 = 0             # two longest downward edge counts through children
        for child in node.children or []:
            h = height[child] + 1
            if h > top1:
                top1, top2 = h, top1
            elif h > top2:
                top2 = h
        height[node] = top1
        best = max(best, top1 + top2)
    return best

