def score_of_students(s: str, answers: List[int]) -> int:
    LIMIT = 1000
    FULL = (1 << (LIMIT + 1)) - 1
    digits = [int(c) for c in s[0::2]]
    ops = s[1::2]
    n = len(digits)

    # Correct value: multiplication before addition.
    total, term = 0, digits[0]
    for op, d in zip(ops, digits[1:]):
        if op == "*":
            term *= d
        else:
            total += term
            term = d
    correct = total + term

    def members(mask):
        out, v = [], 0
        while mask:
            if mask & 1:
                out.append(v)
            mask >>= 1
            v += 1
        return out

    # can[i][j]: bitmask of values (<= LIMIT) operands i..j can produce.
    can = [[0] * n for _ in range(n)]
    vals = [[None] * n for _ in range(n)]
    for i, d in enumerate(digits):
        can[i][i] = 1 << d
        vals[i][i] = [d]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            mask = 0
            for m in range(i, j):
                left, right = vals[i][m], vals[m + 1][j]
                if ops[m] == "+":
                    # Shift the bitmask of the larger side by each value of the smaller side.
                    if len(left) <= len(right):
                        small, big_mask = left, can[m + 1][j]
                    else:
                        small, big_mask = right, can[i][m]
                    for a in small:
                        mask |= big_mask << a
                else:
                    # Times 0 gives 0 even when the other side only had values above LIMIT.
                    if (can[i][m] | can[m + 1][j]) & 1:
                        mask |= 1
                    for a in left:
                        if a == 0:
                            continue
                        cap = LIMIT // a
                        for b in right:
                            if b > cap:
                                break
                            mask |= 1 << (a * b)
            mask &= FULL
            can[i][j] = mask
            vals[i][j] = members(mask)

    reachable = can[0][n - 1]
    score = 0
    for a in answers:
        if a == correct:
            score += 5
        elif (reachable >> a) & 1:
            score += 2
    return score

