def min_or_after_operations(nums: List[int], k: int) -> int:
    zero_mask = 0      # bits we can force to 0 together
    answer = 0
    for b in range(29, -1, -1):
        test = zero_mask | (1 << b)
        ops = 0
        running = test                 # AND of the current group, restricted to test
        for x in nums:
            running &= x
            if running:
                ops += 1               # group not finished: merge with the next element
            else:
                running = test         # group done, start a fresh one
        if ops <= k:
            zero_mask = test
        else:
            answer |= 1 << b
    return answer

