def maximize_square_area(m: int, n: int, hFences: List[int], vFences: List[int]) -> int:
    MOD = 10 ** 9 + 7

    def gaps(fences, end):
        pos = sorted(fences + [1, end])
        return {pos[j] - pos[i] for i in range(len(pos)) for j in range(i + 1, len(pos))}

    heights = gaps(hFences, m)
    best = -1
    for d in gaps(vFences, n):
        if d > best and d in heights:
            best = d
    return -1 if best == -1 else best * best % MOD

def earliest_second_to_mark_indices(nums: List[int], changeIndices: List[int]) -> int:
    n, m = len(nums), len(changeIndices)

    def feasible(t: int) -> bool:
        last = {}
        for s in range(t):
            last[changeIndices[s]] = s           # last appearance within the prefix
        if len(last) < n:
            return False                         # some index can never be marked
        bank = 0
        for s in range(t):
            i = changeIndices[s]
            if last[i] == s:                     # marking moment for index i
                need = nums[i - 1]
                if bank < need:
                    return False
                bank -= need
            else:
                bank += 1                        # a free second for one decrement
        return True

    lo, hi = 1, m + 1                            # hi = m + 1 means "never"
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo if lo <= m else -1

