def minimum_time(hens: List[int], grains: List[int]) -> int:
    hens = sorted(hens)
    grains = sorted(grains)
    m = len(grains)

    def can_finish(t: int) -> bool:
        j = 0                                   # leftmost uneaten grain
        for x in hens:
            if j == m:
                return True
            left = grains[j]
            if left <= x:
                d = x - left
                if d > t:
                    return False                # this grain is out of reach for everyone
                # Grains at or left of x on the way are free once we reach left.
                while j < m and grains[j] <= x:
                    j += 1
                # Extend to the right: best of going left first or right first.
                while j < m and min(2 * d + grains[j] - x, d + 2 * (grains[j] - x)) <= t:
                    j += 1
            else:
                while j < m and grains[j] - x <= t:
                    j += 1
        return j == m

    lo, hi = 0, 2 * 10 ** 9 + 10
    while lo < hi:
        mid = (lo + hi) // 2
        if can_finish(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def get_min_dist_sum(positions: List[List[int]]) -> float:
    pts = [(float(x), float(y)) for x, y in positions]

    def total(cx, cy):
        return sum(math.hypot(cx - x, cy - y) for x, y in pts)

    # 1. Is some customer location itself the geometric median?
    for px, py in set(pts):
        weight = 0
        gx = gy = 0.0
        for x, y in pts:
            d = math.hypot(x - px, y - py)
            if d == 0:
                weight += 1
            else:
                gx += (x - px) / d
                gy += (y - py) / d
        if math.hypot(gx, gy) <= weight + 1e-12:
            return total(px, py)

    # 2. Otherwise run Weiszfeld from the centroid.
    cx = sum(x for x, _ in pts) / len(pts)
    cy = sum(y for _, y in pts) / len(pts)
    for _ in range(100000):
        num_x = num_y = den = 0.0
        hit = False
        for x, y in pts:
            d = math.hypot(cx - x, cy - y)
            if d < 1e-12:
                hit = True
                break
            num_x += x / d
            num_y += y / d
            den += 1.0 / d
        if hit:                                  # nudge off a customer and retry
            cx += 1e-7
            cy += 1e-7
            continue
        nx, ny = num_x / den, num_y / den
        moved = math.hypot(nx - cx, ny - cy)
        cx, cy = nx, ny
        if moved < 1e-10:
            break
    return total(cx, cy)

def longest_obstacle_course_at_each_position(obstacles: List[int]) -> List[int]:
    tails = []          # tails[L] = smallest last height of a course of length L + 1
    ans = []
    for h in obstacles:
        pos = bisect.bisect_right(tails, h)   # courses ending at <= h can take h
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        ans.append(pos + 1)
    return ans

def minimum_lines(points: List[List[int]]) -> int:
    n = len(points)
    full = (1 << n) - 1
    # line[i][j]: mask of every point collinear with points i and j
    line = [[0] * n for _ in range(n)]
    for i in range(n):
        xi, yi = points[i]
        for j in range(n):
            if i == j:
                continue
            xj, yj = points[j]
            mask = 0
            for k, (xk, yk) in enumerate(points):
                if (xj - xi) * (yk - yi) - (yj - yi) * (xk - xi) == 0:
                    mask |= 1 << k
            line[i][j] = mask
    INF = float("inf")
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(full):
        if dp[mask] == INF:
            continue
        i = 0
        while mask >> i & 1:                    # lowest uncovered point
            i += 1
        step = dp[mask] + 1
        nxt = mask | (1 << i)                   # a line through i alone
        if step < dp[nxt]:
            dp[nxt] = step
        for j in range(n):
            if j != i:
                nxt = mask | line[i][j]
                if step < dp[nxt]:
                    dp[nxt] = step
    return dp[full]

def max_ice_cream(costs: List[int], coins: int) -> int:
    top = max(costs)
    count = [0] * (top + 1)
    for c in costs:
        count[c] += 1                    # counting sort buckets
    bought = 0
    for c in range(1, top + 1):
        if coins < c:
            break                        # nothing at this price or above is affordable
        if count[c]:
            take = min(count[c], coins // c)
            bought += take
            coins -= take * c
    return bought

